    """x + gate * LocalBlock(2ch->ch)(ResidualConcat(EffBlock(ch))(x)); gate starts at 0 so the unit begins as identity."""
    def __init__(self, ch, ks, resize_factor, activation):
        super().__init__()
        self.body = nn.Sequential(
            ResidualConcat(EffBlock(ch, ks, resize_factor, activation)),
            LocalBlock(ch * 2, ch, ks, activation))
        self.gate = nn.Parameter(torch.zeros(1))

    def forward(self, x):
        return x + self.gate.to(x.dtype) * self.body(x)


class CellBranch(nn.Module):
    """Per-cell-type readout: returns (mean, log-variance) for one cell type."""
    def __init__(self, in_dim, hidden, activation):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(in_dim, hidden), nn.BatchNorm1d(hidden), activation(),
            nn.Linear(hidden, 2))
        with torch.no_grad():
            last = self.net[-1]
            last.weight[1:].mul_(0.1)
            last.bias[1:].fill_(math.log(0.3))

    def forward(self, h):
        return self.net(h)


def _shift_input(x, s):
    """Shift a (B, C, W) one-hot input by s positions along W, filling the vacated end with zeros (N)."""
    if s == 0:
        return x
    if s > 0:
        return F.pad(x[:, :, s:], (0, s))
    return F.pad(x[:, :, :s], (-s, 0))


class MixHeteroBranchLegNet(nn.Module):
    """LegNet trunk (with a zero-init gated extra unit at the start of stages listed in extra_stages) with manifold
    mixup of the pooled embedding in training and a separate MLP branch per cell type, each giving a mean and a
    log-variance. forward returns the means (B, n_outputs); in training the log-variances are left in
    torch._evoloop_logvar and the mixup (perm, lam) in torch._evoloop_mix for the loss.
    In eval mode the one network is averaged over small input shifts (test-time augmentation; zero-filled ends,
    as seen under outer-flank blanking in training). Training is unchanged."""
    def __init__(self, n_outputs=3, in_ch=4, stem_ch=64, stem_ks=11, ef_ks=9,
                 ef_block_sizes=(128, 160, 192, 256), pool_sizes=(2, 2, 2, 2), resize_factor=4,
                 branch_hidden=256, activation=nn.SiLU, mix_alpha=0.4, mix_prob=0.5, extra_stages=(2, 3),
                 tta_shifts=(-4, -2, 0, 2, 4)):
        super().__init__()
        self.n_outputs = n_outputs
        self.mix_alpha = float(mix_alpha)
        self.mix_prob = float(mix_prob)
        self.tta_shifts = tuple(int(s) for s in tta_shifts)
        self.stem = LocalBlock(in_ch, stem_ch, stem_ks, activation)
        blocks = []
        ch = stem_ch
        for i, (pool, out_ch) in enumerate(zip(pool_sizes, ef_block_sizes)):
            layers = []
            if i in extra_stages:
                layers.append(GatedUnit(ch, ef_ks, resize_factor, activation))
            layers += [
                ResidualConcat(EffBlock(ch, ef_ks, resize_factor, activation)),
                LocalBlock(ch * 2, out_ch, ef_ks, activation),
                nn.MaxPool1d(pool) if pool != 1 else nn.Identity()]
            blocks.append(nn.Sequential(*layers))
            ch = out_ch
        self.main = nn.Sequential(*blocks)
        self.mapper = nn.Sequential(nn.Conv1d(ch, ch * 2, 1, bias=False), nn.BatchNorm1d(ch * 2), activation())
        self.branches = nn.ModuleList([CellBranch(ch * 2, branch_hidden, activation) for _ in range(n_outputs)])

    def _embed(self, x):
        h = self.mapper(self.main(self.stem(x)))
        return F.adaptive_avg_pool1d(h, 1).squeeze(-1)

    def _means(self, h):
        return torch.cat([br(h)[:, 0:1] for br in self.branches], dim=1)

    def forward(self, x):
        if not self.training:
            torch._evoloop_mix = None
            shifts = [s for s in self.tta_shifts if abs(s) < x.shape[2]] or [0]
            acc = None
            for s in shifts:
                mu = self._means(self._embed(_shift_input(x, s))).float()
                acc = mu if acc is None else acc + mu
            return acc / float(len(shifts))
        h = self._embed(x)
        torch._evoloop_mix = None
        if self.mix_alpha > 0 and self.mix_prob > 0 and h.shape[0] > 1:
            b = h.shape[0]
            perm = torch.randperm(b, device=h.device)
            beta = torch.distributions.Beta(torch.tensor(self.mix_alpha), torch.tensor(self.mix_alpha))
            lam = beta.sample((b,)).to(h.device).float()
            lam = torch.maximum(lam, 1.0 - lam)
            use = torch.rand(b, device=h.device) < self.mix_prob
            lam = torch.where(use, lam, torch.ones_like(lam))
            lh = lam[:, None].to(h.dtype)
            h = lh * h + (1 - lh) * h[perm]
            torch._evoloop_mix = (perm, lam)
        outs = [br(h) for br in self.branches]
        mu = torch.cat([o[:, 0:1] for o in outs], dim=1)
        torch._evoloop_logvar = torch.cat([o[:, 1:2] for o in outs], dim=1).float()
        return mu


def build_model(n_outputs=3):
    return MixHeteroBranchLegNet(n_outputs=n_outputs)
# EVOLVE-BLOCK-END

"""Malinois (Gosai et al. 2024): boda2's BassetBranched with the published hyperparameters, and its L1KLmixed
loss. Parameter names match boda2's state dicts, so the published checkpoint and the Basset parent load as is.

conv 300x19 -> BN -> ReLU -> maxpool 3; conv 200x11 -> BN -> ReLU -> maxpool 4; conv 200x7 -> BN -> ReLU ->
pad 1 -> maxpool 4 (same padding throughout); flatten (200 x 13 for 600 bp); linear 1000 -> BN -> ReLU ->
dropout 0.116; three grouped (one per cell type) linear layers of 140 with ReLU and dropout 0.576 between;
one output per cell type.
"""
import math
import torch
import torch.nn as nn
import torch.nn.functional as F


class ConvNorm(nn.Module):
    def __init__(self, cin, cout, k):
        super().__init__()
        self.conv = nn.Conv1d(cin, cout, k)
        self.bn_layer = nn.BatchNorm1d(cout)
        self.pad = ((k - 1) // 2, k - 1 - (k - 1) // 2)

    def forward(self, x):
        return self.bn_layer(self.conv(F.pad(x, self.pad)))


class LinearNorm(nn.Module):
    def __init__(self, cin, cout):
        super().__init__()
        self.linear = nn.Linear(cin, cout)
        self.bn_layer = nn.BatchNorm1d(cout)

    def forward(self, x):
        return self.bn_layer(self.linear(x))


class GroupedLinear(nn.Module):
    """One independent linear map per group: (B, groups * cin) -> (B, groups * cout)."""

    def __init__(self, cin, cout, groups):
        super().__init__()
        self.cin, self.cout, self.groups = cin, cout, groups
        self.weight = nn.Parameter(torch.zeros(groups, cin, cout))
        self.bias = nn.Parameter(torch.zeros(groups, 1, cout))
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(3))
        bound = 1 / math.sqrt(nn.init._calculate_fan_in_and_fan_out(self.weight)[0])
        nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x):
        h = x.permute(1, 0).reshape(self.groups, self.cin, -1).permute(0, 2, 1)
        h = torch.bmm(h, self.weight) + self.bias
        return h.permute(0, 2, 1).reshape(self.cout * self.groups, -1).permute(1, 0)


class Branched(nn.Module):
    def __init__(self, cin, hidden, n_branches, n_layers, dropout):
        super().__init__()
        self.n_branches, self.n_layers = n_branches, n_layers
        self.dropout = nn.Dropout(dropout)
        size = cin
        for i in range(n_layers):
            setattr(self, f"branched_layer_{i + 1}", GroupedLinear(size, hidden, n_branches))
            size = hidden

    def forward(self, x):
        h = x.repeat(1, self.n_branches)
        for i in range(self.n_layers - 1):
            h = self.dropout(F.relu(getattr(self, f"branched_layer_{i + 1}")(h)))
        return getattr(self, f"branched_layer_{self.n_layers}")(h)


class Malinois(nn.Module):
    def __init__(self, input_len=600, n_outputs=3, linear_dropout=0.11625456877954289,
                 branched_dropout=0.5757068086404574):
        super().__init__()
        self.conv1 = ConvNorm(4, 300, 19)
        self.conv2 = ConvNorm(300, 200, 11)
        self.conv3 = ConvNorm(200, 200, 7)
        flat = ((input_len // 3 // 4) + 2) // 4
        self.linear1 = LinearNorm(200 * flat, 1000)
        self.dropout = nn.Dropout(linear_dropout)
        self.branched = Branched(1000, 140, n_outputs, 3, branched_dropout)
        self.output = GroupedLinear(140, 1, n_outputs)

    def forward(self, x):
        """x: one-hot (B, 4, 600)."""
        h = F.max_pool1d(F.relu(self.conv1(x)), 3)
        h = F.max_pool1d(F.relu(self.conv2(h)), 4)
        h = F.max_pool1d(F.pad(F.relu(self.conv3(h)), (1, 1)), 4)
        h = self.dropout(F.relu(self.linear1(h.flatten(1))))
        return self.output(self.branched(h))


def l1_kl_mixed(pred, target, alpha=1.0, beta=5.0):
    """boda2 L1KLmixed (reduction 'mean'): L1 plus KL between the softmaxes over cell types, averaged over
    all elements, (alpha * L1 + beta * KL) / (alpha + beta)."""
    lp = pred - torch.logsumexp(pred, -1, keepdim=True)
    lt = target - torch.logsumexp(target, -1, keepdim=True)
    kl = F.kl_div(lp, lt, reduction="mean", log_target=True)
    return (alpha * F.l1_loss(pred, target) + beta * kl) / (alpha + beta)


def build_model():
    """Malinois with the published hyperparameters: (B, 4, 600) one-hot -> (B, 3)."""
    return Malinois()

